        "trecho": "O volume de leitores de e-books tem crescido consideravelmente nas últimas décadas, impulsionado pelo avanço da tecnologia e pela popularização de dispositivos móveis. Desde o lançamento do primeiro leitor digital no Brasil, em 2007, os e-books passaram a se tornar uma alternativa acessível e prátic",
