        "autor": "",
        "trecho": "A pandemia mudou os hábitos de lazer em todo o mundo. O livro está se tornando um aliado e companheiro fiel nos dias de hoje, quando reuniões com amigos ou espetáculos estão proibidos. No entanto, o leitor encontrou as livrarias fechadas. O aumento da leitura no formato digital já vinha sendo confir",
